// 真实Common保存点/捕获的连续读门；不以局部前界替代advance、条件史或业务授权。
#include "resident/storage/common_codec.hpp"
#include <iostream>
#include <stdexcept>
using namespace hanmo::resident;
namespace {
int checks=0;
// 失败停在首个真实反例，不将数量解释为World验收。
void need(bool ok,const char* message){++checks;if(!ok)throw std::runtime_error(message);}
// 只建原Common人物写及序列化所需最小输入。
CommonStore initial(){auto cat=std::make_shared<CommonCatalog>();CommonState s;s.identity.tick=4;s.identity.revision=3;s.next_instance_id=20;ActorRecord a;a.id="p";a.hp=90;a.fatigue=5;s.actors.insert(a.id,a);return CommonStore(std::move(s),std::move(cat));}
// 读取与生命周期护栏没有新增持久段，回滚应恢复原Common完整字节。
bool same(const CommonStore& a,const CommonStore& b){return compare_boundary(encode_common_state(a.state()),encode_common_state(b.state())).exact();}
}
int main(){try{
 auto c=initial(),original=initial();need(!c.actor_condition_savepoint_boundary().ok,"capture is necessary");ActorConditionSavepointBoundary empty;need(!c.validate_actor_condition_savepoint_boundary(empty).ok,"empty read is not a boundary");need(c.begin_actor_condition_capture().ok,"capture begin");auto before=c.actor_condition_savepoint_boundary();need(before.ok&&c.validate_actor_condition_savepoint_boundary(before.value).ok,"true boundary accepted");need(same(c,original),"reading boundary does not write Common bytes");
 auto point=c.begin_savepoint();need(point.ok&&!c.validate_actor_condition_savepoint_boundary(before.value).ok,"begin invalidates prior continuous read");auto inside=c.actor_condition_savepoint_boundary();need(inside.ok&&c.validate_actor_condition_savepoint_boundary(inside.value).ok,"read in actual savepoint");need(c.commit_savepoint(point.value).ok&&!c.validate_actor_condition_savepoint_boundary(inside.value).ok,"commit invalidates in-savepoint read");need(!c.validate_actor_condition_savepoint_boundary(before.value).ok&&same(c,original),"no-write commit cannot revive old equal-state boundary");
 auto fresh=c.actor_condition_savepoint_boundary();need(fresh.ok,"fresh after commit");point=c.begin_savepoint();auto read=c.actor_condition_savepoint_boundary();need(point.ok&&read.ok,"actual rollback frame");auto id=c.next_id("test");need(id.ok&&c.append_fact({id.value,"test","test"}).ok,"real allocation and fact");ActorMutation m;m.actor_id="p";m.hp=80;need(c.apply_actor(m).ok,"real condition write");need(c.rollback_savepoint(point.value).ok&&same(c,original),"rollback restores all actual persistent writes");need(!c.validate_actor_condition_savepoint_boundary(read.value).ok&&!c.validate_actor_condition_savepoint_boundary(fresh.value).ok,"restored values do not restore lifecycle boundary");need(c.actor_condition_execution_drafts().empty(),"original draft rollback remains exact");
 point=c.begin_savepoint();read=c.actor_condition_savepoint_boundary();need(point.ok&&read.ok&&c.rollback_savepoint(point.value).ok,"empty rollback also real lifecycle");need(!c.validate_actor_condition_savepoint_boundary(read.value).ok,"empty rollback invalidates");read=c.actor_condition_savepoint_boundary();need(read.ok,"fresh stable read");need(!c.rollback_savepoint(-1).ok&&c.validate_actor_condition_savepoint_boundary(read.value).ok,"failed stale rollback changes no lifecycle");
 CommonStore clone(c);need(!clone.validate_actor_condition_savepoint_boundary(read.value).ok,"copy cannot inherit original capture or boundary");need(c.validate_actor_condition_savepoint_boundary(read.value).ok,"copy leaves original read intact");need(c.finish_actor_condition_capture().ok&&!c.validate_actor_condition_savepoint_boundary(read.value).ok,"finish invalidates capture read");need(c.begin_actor_condition_capture().ok&&!c.validate_actor_condition_savepoint_boundary(read.value).ok,"same address new capture cannot revive read");read=c.actor_condition_savepoint_boundary();CommonStore moved(std::move(c));need(!moved.validate_actor_condition_savepoint_boundary(read.value).ok&&!c.validate_actor_condition_savepoint_boundary(read.value).ok,"move clears both capture owners");
 auto target=initial();need(target.begin_actor_condition_capture().ok,"copy assignment fixture");read=target.actor_condition_savepoint_boundary();target=original;need(!target.validate_actor_condition_savepoint_boundary(read.value).ok,"copy assignment invalidates old capture read");need(target.begin_actor_condition_capture().ok,"move assignment fixture");read=target.actor_condition_savepoint_boundary();auto source=initial();target=std::move(source);need(!target.validate_actor_condition_savepoint_boundary(read.value).ok,"move assignment invalidates old capture read");
 auto limitation=initial();need(limitation.begin_actor_condition_capture().ok,"finite guarantee fixture");read=limitation.actor_condition_savepoint_boundary();m.hp=75;need(limitation.apply_actor(m).ok&&limitation.validate_actor_condition_savepoint_boundary(read.value).ok,"boundary alone is not actor read-version or source proof");need(limitation.finish_actor_condition_capture().ok,"original finish remains available");
 std::cout<<"ACTOR_CONDITION_SAVEPOINT_BOUNDARY "<<checks<<"/0 COMMON_LIFECYCLE_ONLY\n";return 0;
}catch(const std::exception& e){std::cerr<<"ACTOR_CONDITION_SAVEPOINT_BOUNDARY "<<checks<<"/1 "<<e.what()<<'\n';return 1;}}
